mapper.select:
SELECT GROUP_CONCAT(l.id) AS level_id, GROUP_CONCAT(l.level_name) AS level_name, GROUP_CONCAT(p.id) AS post_id, GROUP_CONCAT(p.post_name) AS post_name, MAX(m.id) AS id, ANY_VALUE(mur.user_id) AS user_id, ANY_VALUE(u.nick_name) AS member_name FROM org_member m LEFT JOIN org_member_user_rel mur ON m.id = mur.member_id LEFT JOIN org_member_post_rel mpr ON m.id = mpr.member_id LEFT JOIN org_post p ON p.id = mpr.post_id LEFT JOIN org_level l ON l.id = mpr.level_id LEFT JOIN sys_user u ON u.user_id = mur.user_id
u.del_flag != 2
AND m.member_name LIKE CONCAT('%',#{orgMemberPageDTO.searchValue},'%')
AND l.id IN
#{item}
AND mur.user_id IN
#{item}
AND p.id IN
#{item}
GROUP BY m.id

SELECT om.id, om.member_name, ompl.level_id, ol.level_name, ompl.post_id, op.post_name, FROM org_member_post_rel ompl LEFT JOIN org_member om ON om.id = ompl.member_id LEFT JOIN org_level ol ON ol.id = ompl.level_id LEFT JOIN org_post op ON op.id = ompl.post_id WHERE ompl.level_id IN
#{levelId}
AND ompl.lead_flag = #{leadFlag}

SELECT omur.user_id, om.id, om.member_name FROM org_level_post_rel olpr LEFT JOIN org_member_post_rel ompr ON ompr.post_id = olpr.post_id LEFT JOIN org_member om ON ompr.member_id = om.id LEFT JOIN org_member_user_rel omur ON ompr.member_id = omur.member_id WHERE a.account_id = #{accountId} olpr.level_id IN
#{levelId}
AND olpr.lead_flag = #{leadFlag}
